import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER || 'webapp',
  password: process.env.DB_PASS || 'changeme',
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Session store - in-memory for simplicity
const sessions = new Map();

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });

  const hash = crypto.createHash('sha256').update(password).digest('hex');
  try {
    const result = await pool.query(
      'SELECT id, username, role FROM users WHERE username = $1 AND password_hash = $2',
      [username, hash]
    );
    if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });

    const token = crypto.randomBytes(32).toString('hex');
    sessions.set(token, { userId: result.rows[0].id, role: result.rows[0].role });
    res.json({ token, user: result.rows[0] });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

function authenticate(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token || !sessions.has(token)) return res.status(401).json({ error: 'Unauthorized' });
  req.session = sessions.get(token);
  next();
}

// VULNERABLE: IDOR - no authorization check on userId parameter
app.get('/api/users/:userId/documents', authenticate, async (req, res) => {
  const { userId } = req.params;
  const { category, sort } = req.query;

  // Build query with parameterized userId but injectable sort
  let query = 'SELECT id, title, created_at, category FROM documents WHERE owner_id = $1';
  const params = [userId];

  if (category) {
    params.push(category);
    query += ` AND category = $${params.length}`;
  }

  // VULNERABLE: SQL injection via ORDER BY clause
  if (sort) {
    query += ` ORDER BY ${sort}`;
  } else {
    query += ' ORDER BY created_at DESC';
  }

  try {
    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (e) {
    // Error message leaks query structure
    res.status(500).json({ error: 'Query failed', detail: e.message });
  }
});

app.get('/api/users/:userId/profile', authenticate, async (req, res) => {
  const { userId } = req.params;
  try {
    const result = await pool.query(
      'SELECT id, username, email, department, role FROM users WHERE id = $1',
      [userId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json({ profile: result.rows[0] });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

app.put('/api/users/:userId/profile', authenticate, async (req, res) => {
  const { userId } = req.params;
  // At least checks ownership here
  if (req.session.userId !== parseInt(userId)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const { email, department } = req.body;
  try {
    await pool.query(
      'UPDATE users SET email = $1, department = $2 WHERE id = $3',
      [email, department, userId]
    );
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, '0.0.0.0', () => {
  console.log('Document service listening on :3000');
});
